import { getMetaContent } from "helpers/meta_helpers"

const LOCALE = "en-US"
const MILLISECONDS_PER_DAY = 24 * 60 * 60 * 1000
const DAYS_PER_WEEK = 7

export function signedDifferenceInDays(fromDate, toDate) {
  return Math.round((beginningOfDay(toDate) - beginningOfDay(fromDate)) / MILLISECONDS_PER_DAY)
}

export function beginningOfDay(date) {
  const { year, month, day } = datePartsInTimezone(date)
  return new Date(Date.UTC(year, month - 1, day))
}

// "1:42 PM"
export function formatTime(date) {
  return format(date, { hour: "numeric", minute: "2-digit" })
}

// "Sep 12", or "Sep 12, 2024" when the date falls outside the current year
export function formatDate(date, now = new Date()) {
  if (datePartsInTimezone(date).year === datePartsInTimezone(now).year) {
    return format(date, { month: "short", day: "numeric" })
  } else {
    return formatFullDate(date)
  }
}

// "Sep 12, 2025"
export function formatFullDate(date) {
  return format(date, { month: "short", day: "numeric", year: "numeric" })
}

// "Friday, September 12"
export function formatLongDate(date) {
  return format(date, { weekday: "long", month: "long", day: "numeric" })
}

// "9/12/25, 1:42 PM"
export function formatDateTime(date) {
  return format(date, { dateStyle: "short", timeStyle: "short" })
}

// "Friday, September 12, 2025 at 1:42 PM"
export function formatFullDateTime(date) {
  return format(date, { dateStyle: "full", timeStyle: "short" })
}

// "1:42 PM" for today, "yesterday" or "tomorrow" for the adjacent days, "5 days ago" or
// "in 3 days" within a week, and the plain date ("Sep 12") for anything further away.
export function formatRelativeDate(date, now = new Date()) {
  const days = signedDifferenceInDays(now, date)

  if (days === 0) {
    return formatTime(date)
  } else if (days === -1) {
    return "yesterday"
  } else if (days === 1) {
    return "tomorrow"
  } else if (days < 0 && days > -DAYS_PER_WEEK) {
    return `${-days} days ago`
  } else if (days > 0 && days < DAYS_PER_WEEK) {
    return `in ${days} days`
  } else {
    return formatDate(date, now)
  }
}

function datePartsInTimezone(date) {
  return dateFormatter().formatToParts(date).reduce((parts, { type, value }) => {
    if (type !== "literal") parts[type] = parseInt(value, 10)
    return parts
  }, {})
}

function dateFormatter() {
  return formatter({ year: "numeric", month: "2-digit", day: "2-digit" })
}

function format(date, options) {
  return formatter(options).format(date)
}

// Format in the timezone the server rendered with (the `timezone` meta tag), so client-side
// times and day boundaries match the server's instead of following the browser's resolved
// timezone, which can differ in a PWA. Formatters are cached, since they're expensive to build.
let formatters = new Map()
let formattersTimezone

function formatter(options) {
  const timezone = getMetaContent("timezone")
  const key = JSON.stringify(options)

  if (formattersTimezone !== timezone) {
    formattersTimezone = timezone
    formatters = new Map()
  }

  if (!formatters.has(key)) {
    formatters.set(key, buildFormatter(options, timezone))
  }

  return formatters.get(key)
}

function buildFormatter(options, timezone) {
  try {
    return new Intl.DateTimeFormat(LOCALE, { ...options, timeZone: timezone })
  } catch {
    return new Intl.DateTimeFormat(LOCALE, options)
  }
}
